+          int a = zone_vert_off[z - 1] + static_cast<int>(conn[2 * e]) - 1;
+          int b = zone_vert_off[z - 1] + static_cast<int>(conn[2 * e + 1]) - 1;
+          if (a < 0 || a >= static_cast<int>(oldvx.size()) || b < 0 || b >= static_cast<int>(oldvx.size()))
+            bad("boundary element vertex index out of range");
+          raw_edges.push_back({newid[a], newid[b], tag});
+        }
+      } else if (et == CGNS_ENUMV(NODE) || et == CGNS_ENUMV(BAR_3)) {
+        / Not used by the supplied meshes; skip point/quadratic boundary sets.
+      } else {
+        bad("unsupported CGNS element type in section '" + std::string(sname) + "'");
+      }
+    }
+  }
+  for (int i = 0; i < static_cast<int>(total_cells); ++i)
+    if (!cell_set[i]) bad("CGNS mesh did not define every cell in the zone range");
+
+  g.ncells = static_cast<int>(total_cells);
+  g.cell_zone.resize(g.ncells);
+  g.cell_nv.resize(g.ncells);
+  g.cell_vert_off.assign(g.ncells + 1, 0);
+  g.cell_verts.clear();
+  for (int i = 0; i < g.ncells; ++i) {
+    const RawCell& rc = raw_cells[i];
+    if (rc.nv != 3 && rc.nv != 4) bad("internal: unsupported cell vertex count");
+    g.cell_zone[i] = rc.zone;
+    g.cell_nv[i] = rc.nv;
+    for (int k = 0; k < rc.nv; ++k) g.cell_verts.push_back(rc.v[k]);
+    g.cell_vert_off[i + 1] = static_cast<int>(g.cell_verts.size());
+  }
+  g.family_names = std::move(family_names);
+
+  / Keep raw boundary edges for topology construction.
+  g.vol.assign(g.ncells, 0.0);
+  g.cx.assign(g.ncells, 0.0);
+  g.cy.assign(g.ncells, 0.0);
+  for (int i = 0; i < g.ncells; ++i) {
+    int off = g.cell_vert_off[i], nv = g.cell_nv[i];
+    double a2 = 0.0, cx = 0.0, cy = 0.0;
+    for (int k = 0; k < nv; ++k) {
+      int a = g.cell_verts[off + k];
+      int b = g.cell_verts[off + (k + 1) % nv];
+      double cr = g.vx[a] * g.vy[b] - g.vx[b] * g.vy[a];
+      a2 += cr;
+      cx += (g.vx[a] + g.vx[b]) * cr;
+      cy += (g.vy[a] + g.vy[b]) * cr;
+    }
+    if (std::abs(a2) < 1e-24) bad("degenerate cell with zero area");
+    if (a2 < 0.0) {
+      std::reverse(g.cell_verts.begin() + off, g.cell_verts.begin() + off + nv);
+      a2 = -a2;
+      cx = -cx;
+      cy = -cy;
+    }
+    g.vol[i] = 0.5 * a2;
+    g.cx[i] = cx / (3.0 * a2);
+    g.cy[i] = cy / (3.0 * a2);
+  }
+
+  / Build unique faces.
+  std::unordered_map<uint64_t, int> face_index;
+  face_index.reserve(static_cast<size_t>(4) * g.ncells);
+  std::vector<std::vector<int>> cell_faces(g.ncells);
+  g.faces.clear();
+  g.faces.reserve(static_cast<size_t>(2.2) * g.ncells);
+  for (int i = 0; i < g.ncells; ++i) {
+    int off = g.cell_vert_off[i], nv = g.cell_nv[i];
+    for (int k = 0; k < nv; ++k) {
+      int va = g.cell_verts[off + k];
+      int vb = g.cell_verts[off + (k + 1) % nv];
+      uint64_t key = edge_key(va, vb);
+      auto it = face_index.find(key);
+      if (it == face_index.end()) {
+        int fid = static_cast<int>(g.faces.size());
+        g.faces.push_back({i, -1, -1, va, vb});
+        face_index.emplace(key, fid);
+        cell_faces[i].push_back(fid);
+      } else {
+        GlobalFace& f = g.faces[it->second];
+        if (f.c1 != -1) bad("non-manifold edge shared by more than two cells");
+        f.c1 = i;
+        cell_faces[i].push_back(it->second);
+      }
+    }
+  }
+
+  std::unordered_map<uint64_t, int> boundary_tag;
+  boundary_tag.reserve(raw_edges.size() * 2 + 1);
+  for (const RawEdge& e : raw_edges) {
+    uint64_t key = edge_key(e.v0, e.v1);
+    auto [it, inserted] = boundary_tag.emplace(key, e.tag);
+    if (!inserted && it->second != e.tag) bad("boundary edge belongs to two different families");
+  }
+  g.n_boundary_faces = 0;
+  g.n_interior_faces = 0;
+  for (GlobalFace& f : g.faces) {
+    if (f.c1 < 0) {
+      uint64_t key = edge_key(f.v0, f.v1);
+      auto it = boundary_tag.find(key);
+      if (it == boundary_tag.end()) {
+        char buf[256];
+        std::snprintf(buf, sizeof(buf),
+                      "boundary edge (%.6g,%.6g)-(%.6g,%.6g) has no CGNS boundary family",
+                      g.vx[f.v0], g.vy[f.v0], g.vx[f.v1], g.vy[f.v1]);
+        bad(buf);
+      }
+      f.tag = it->second;
+      ++g.n_boundary_faces;
+    } else {
+      ++g.n_interior_faces;
+    }
+  }
+
+  g.cell_face_off.assign(g.ncells + 1, 0);
+  for (int i = 0; i < g.ncells; ++i)
+    g.cell_face_off[i + 1] = g.cell_face_off[i] + static_cast<int>(cell_faces[i].size());
+  g.cell_faces.clear();
+  g.cell_faces.reserve(g.cell_face_off.back());
+  for (int i = 0; i < g.ncells; ++i)
+    g.cell_faces.insert(g.cell_faces.end(), cell_faces[i].begin(), cell_faces[i].end());
+
+  / Validate that every boundary face maps to a requested family.
+  for (int i = 0; i < g.ncells; ++i) {
+    if (g.cell_face_off[i + 1] - g.cell_face_off[i] != g.cell_nv[i])
+      bad("internal: face incidence count does not match cell vertex count");
+  }
+  return g;
+}
+
+void build_geometry_and_topology(GlobalMesh&) {
+  / Geometry and topology are constructed in read_global_mesh so that the raw
+  / boundary-family map remains available.  This function is kept as a stable
+  / extension point for future 3-D mesh types.
+}
+
+std::vector<int> partition_mesh(const GlobalMesh& mesh, int nparts, int& edge_cut) {
+  if (nparts < 1) bad("number of MPI ranks must be positive");
+  std::vector<std::vector<int>> adj(mesh.ncells);
+  for (const GlobalFace& f : mesh.faces) {
+    if (f.c1 >= 0) {
+      adj[f.c0].push_back(f.c1);
+      adj[f.c1].push_back(f.c0);
+    }
+  }
+  std::vector<idx_t> xadj(mesh.ncells + 1, 0);
+  std::vector<idx_t> adjncy;
+  adjncy.reserve(static_cast<size_t>(4) * mesh.ncells);
+  for (int i = 0; i < mesh.ncells; ++i) {
+    auto& a = adj[i];
+    std::sort(a.begin(), a.end());
+    a.erase(std::unique(a.begin(), a.end()), a.end());
+    xadj[i] = static_cast<idx_t>(adjncy.size());
+    for (int j : a) adjncy.push_back(static_cast<idx_t>(j));
+  }
+  xadj[mesh.ncells] = static_cast<idx_t>(adjncy.size());
+
+  idx_t nv = static_cast<idx_t>(mesh.ncells);
+  idx_t ncon = 1;
+  idx_t np = static_cast<idx_t>(nparts);
+  idx_t objval = 0;
+  std::vector<idx_t> part(mesh.ncells, 0);
+  idx_t options[METIS_NOPTIONS];
+  METIS_SetDefaultOptions(options);
+  options[METIS_OPTION_NUMBERING] = 0;
+  int ier = METIS_PartGraphKway(&nv, &ncon, xadj.data(), adjncy.data(), nullptr, nullptr,
+                                nullptr, &np, nullptr, nullptr, options, &objval, part.data());
+  if (ier != METIS_OK) bad("METIS_PartGraphKway failed with status " + std::to_string(ier));
+  edge_cut = static_cast<int>(objval);
+  std::vector<int> out(mesh.ncells);
+  for (int i = 0; i < mesh.ncells; ++i) {
+    out[i] = static_cast<int>(part[i]);
+    if (out[i] < 0 || out[i] >= nparts) bad("METIS returned an invalid partition id");
+  }
+  return out;
+}
+
+std::vector<LocalMesh> build_local_meshes(const GlobalMesh& g,
+                                          const std::vector<int>& part,
+                                          const std::map<std::string, BoundaryKind>& bc_map) {
+  if (static_cast<int>(part.size()) != g.ncells) bad("internal: partition size mismatch");
+  int nparts = 0;
+  for (int p : part) nparts = std::max(nparts, p + 1);
+  std::vector<std::vector<int>> owned(nparts);
+  for (int i = 0; i < g.ncells; ++i) owned[part[i]].push_back(i);
+  std::vector<std::vector<int>> global_to_local(nparts, std::vector<int>(g.ncells, -1));
+  for (int r = 0; r < nparts; ++r)
+    for (int k = 0; k < static_cast<int>(owned[r].size()); ++k) global_to_local[r][owned[r][k]] = k;
+
+  std::vector<LocalMesh> locals(nparts);
+  for (int r = 0; r < nparts; ++r) {
+    LocalMesh lm;
+    lm.n_owned = static_cast<int>(owned[r].size());
+    if (lm.n_owned == 0) bad("METIS produced an empty rank partition");
+    lm.cx.resize(lm.n_owned);
+    lm.cy.resize(lm.n_owned);
+    lm.vol.resize(lm.n_owned);
+    lm.cell_nv.resize(lm.n_owned);
+    lm.cell_vert_off.assign(lm.n_owned + 1, 0);
+    lm.cell_type.resize(lm.n_owned);
+    lm.cell_face_off.assign(lm.n_owned + 1, 0);
+    lm.cell_verts.reserve(static_cast<size_t>(4) * lm.n_owned);
+    lm.cell_vert_x.reserve(static_cast<size_t>(4) * lm.n_owned);
+    lm.cell_vert_y.reserve(static_cast<size_t>(4) * lm.n_owned);
+    lm.faces.reserve(static_cast<size_t>(4) * lm.n_owned);
+    std::unordered_map<int, int> remote_ghost_index;
+    remote_ghost_index.reserve(static_cast<size_t>(2) * lm.n_owned);
+
+    for (int li = 0; li < lm.n_owned; ++li) {
+      int gid = owned[r][li];
+      lm.cx[li] = g.cx[gid];
+      lm.cy[li] = g.cy[gid];
+      lm.vol[li] = g.vol[gid];
+      int nv = g.cell_nv[gid];
+      lm.cell_nv[li] = nv;
+      lm.cell_type[li] = nv;
+      int off = g.cell_vert_off[gid];
+      for (int k = 0; k < nv; ++k) {
+        int vid = g.cell_verts[off + k];
+        lm.cell_verts.push_back(vid);
+        lm.cell_vert_x.push_back(g.vx[vid]);
+        lm.cell_vert_y.push_back(g.vy[vid]);
+      }
+      lm.cell_vert_off[li + 1] = static_cast<int>(lm.cell_verts.size());
+
+      for (int fi = g.cell_face_off[gid]; fi < g.cell_face_off[gid + 1]; ++fi) {
+        int fid = g.cell_faces[fi];
+        const GlobalFace& gf = g.faces[fid];
+        int other_global = (gf.c0 == gid) ? gf.c1 : gf.c0;
+        double dx = g.vx[gf.v1] - g.vx[gf.v0];
+        double dy = g.vy[gf.v1] - g.vy[gf.v0];
+        double len = std::hypot(dx, dy);
+        if (!(len > 0.0)) bad("degenerate mesh face");
+        double nx = dy / len;
+        double ny = -dx / len;
+        if (gf.c0 != gid) { nx = -nx; ny = -ny; }
+        LocalFace lf;
+        lf.cell = li;
+        lf.tag = -1;
+        lf.bc = 0;
+        lf.nx = nx;
+        lf.ny = ny;
+        lf.area = len;
+        lf.xf = 0.5 * (g.vx[gf.v0] + g.vx[gf.v1]);
+        lf.yf = 0.5 * (g.vy[gf.v0] + g.vy[gf.v1]);
+        if (other_global >= 0) {
+          if (part[other_global] == r) {
+            lf.nb = global_to_local[r][other_global];
+          } else {
+            auto it = remote_ghost_index.find(other_global);
+            int gi;
+            if (it == remote_ghost_index.end()) {
+              gi = lm.n_owned + static_cast<int>(lm.ghosts.size());
+              remote_ghost_index.emplace(other_global, gi);
+              GhostCell gc;
+              gc.kind = 0;
+              gc.owner_rank = part[other_global];
+              gc.remote_idx = global_to_local[gc.owner_rank][other_global];
+              lm.ghosts.push_back(gc);
+            } else {
+              gi = it->second;
+            }
+            lf.nb = gi;
+          }
+        } else {
+          std::string fam = g.family_names.at(static_cast<size_t>(gf.tag));
+          auto itbc = bc_map.find(fam);
+          if (itbc == bc_map.end())
+            bad("mesh boundary family '" + fam + "' is not mapped in the case boundary_conditions");
+          BoundaryKind bk = itbc->second;
+          int gi = lm.n_owned + static_cast<int>(lm.ghosts.size());
+          GhostCell gc;
+          gc.kind = static_cast<int>(bk);
+          gc.bc_owner = li;
+          gc.tag = gf.tag;
+          gc.nx = nx;
+          gc.ny = ny;
+          gc.xf = lf.xf;
+          gc.yf = lf.yf;
+          lm.ghosts.push_back(gc);
+          lf.nb = gi;
+          lf.bc = static_cast<int>(bk);
+          lf.tag = gf.tag;
+          ++lm.n_boundary_faces;
+        }
+        lm.faces.push_back(lf);
+      }
+      lm.cell_face_off[li + 1] = static_cast<int>(lm.faces.size());
+    }
+
+    lm.n_remote_ghosts = 0;
+    for (const GhostCell& gc : lm.ghosts)
+      if (gc.kind == 0) ++lm.n_remote_ghosts;
+    lm.n_bc_ghosts = static_cast<int>(lm.ghosts.size()) - lm.n_remote_ghosts;
+    lm.n_local = lm.n_owned + static_cast<int>(lm.ghosts.size());
+    lm.cx.resize(lm.n_local);
+    lm.cy.resize(lm.n_local);
+    lm.vol.resize(lm.n_local);
+    for (int gi = 0; gi < lm.n_remote_ghosts; ++gi) {
+      / Remote ghosts are stored first, before boundary ghosts.
+      GhostCell& gc = lm.ghosts[gi];
+      / Recover global id through the owner-local mapping.
+      int gid = owned[gc.owner_rank][gc.remote_idx];
+      lm.cx[lm.n_owned + gi] = g.cx[gid];
+      lm.cy[lm.n_owned + gi] = g.cy[gid];
+      lm.vol[lm.n_owned + gi] = g.vol[gid];
+    }
+    for (int gi = lm.n_remote_ghosts; gi < static_cast<int>(lm.ghosts.size()); ++gi) {
+      GhostCell& gc = lm.ghosts[gi];
+      int oi = gc.bc_owner;
+      double d = (lm.cx[oi] - gc.xf) * gc.nx + (lm.cy[oi] - gc.yf) * gc.ny;
+      if (!(d < 0.0)) bad("internal: boundary ghost is on the wrong side of a face");
+      lm.cx[lm.n_owned + gi] = lm.cx[oi] - 2.0 * d * gc.nx;
+      lm.cy[lm.n_owned + gi] = lm.cy[oi] - 2.0 * d * gc.ny;
+      lm.vol[lm.n_owned + gi] = lm.vol[oi];
+      gc.dist = -2.0 * d;
+    }
+    locals[r] = std::move(lm);
+  }
+
+  / Build halo exchange lists.  Recv order defines the matching send order.
+  std::vector<std::map<int, std::vector<std::pair<int, int>>>> recv(nparts);
+  for (int r = 0; r < nparts; ++r) {
+    for (int gi = 0; gi < static_cast<int>(locals[r].ghosts.size()); ++gi) {
+      const GhostCell& gc = locals[r].ghosts[gi];
+      if (gc.kind == 0)
+        recv[r][gc.owner_rank].push_back({locals[r].n_owned + gi, gc.remote_idx});
+    }
+  }
+  std::vector<std::map<int, std::vector<int>>> send(nparts);
+  for (int r = 0; r < nparts; ++r) {
+    for (const auto& [q, entries] : recv[r]) {
+      for (const auto& [ghost_idx, remote_idx] : entries)
+        send[q][r].push_back(remote_idx);
+    }
+  }
+  for (int r = 0; r < nparts; ++r) {
+    LocalMesh& lm = locals[r];
+    lm.neighbors.clear();
+    lm.recv_off.assign(1, 0);
+    lm.send_off.assign(1, 0);
+    lm.recv_cells.clear();
+    lm.send_cells.clear();
+    for (const auto& [q, entries] : recv[r]) {
+      lm.neighbors.push_back(q);
+      for (const auto& [ghost_idx, remote_idx] : entries) lm.recv_cells.push_back(ghost_idx);
+      lm.recv_off.push_back(static_cast<int>(lm.recv_cells.size()));
+    }
+    for (const auto& [q, cells] : send[r]) {
+      const auto& rv = lm.neighbors;
+      if (std::find(rv.begin(), rv.end(), q) == rv.end())
+        bad("internal: halo send/recv neighbour mismatch");
+      for (int c : cells) lm.send_cells.push_back(c);
+      lm.send_off.push_back(static_cast<int>(lm.send_cells.size()));
+    }
+    / send_off is ordered by neighbour rank, while lm.neighbors is sorted by
+    / rank as well (std::map iteration).
+  }
+  return locals;
+}
+
+GlobalInfo make_global_info(const GlobalMesh& mesh, const std::vector<LocalMesh>& locals,
+                            const std::string& mesh_file, const std::string& mesh_key,
+                            int edge_cut) {
+  GlobalInfo info;
+  info.nparts = static_cast<int>(locals.size());
+  info.nverts = mesh.nverts;
+  info.ncells = mesh.ncells;
+  info.nfaces = static_cast<int>(mesh.faces.size());
+  info.n_boundary_faces = mesh.n_boundary_faces;
+  info.partition_edge_cut = edge_cut;
+  info.mesh_file = mesh_file;
+  info.mesh_key = mesh_key;
+  info.family_names = mesh.family_names;
+  info.ranks.resize(locals.size());
+  for (size_t r = 0; r < locals.size(); ++r) {
+    const LocalMesh& lm = locals[r];
+    RankStats& s = info.ranks[r];
+    s.owned = lm.n_owned;
+    s.remote_ghosts = lm.n_remote_ghosts;
+    s.bc_ghosts = lm.n_bc_ghosts;
+    s.boundary_faces = lm.n_boundary_faces;
+    s.neighbor_ranks = static_cast<int>(lm.neighbors.size());
+    s.send_cells = static_cast<int>(lm.send_cells.size());
+    s.recv_cells = static_cast<int>(lm.recv_cells.size());
+    s.neighbors = lm.neighbors;
+  }
+  return info;
+}
+
+void write_local_mesh(const LocalMesh& m, const std::string& path) {
+  std::ofstream out(path, std::ios::binary);
+  if (!out) bad("cannot write partition cache: " + path);
+  uint32_t magic = 0x43464432u, version = 3;
+  write_scalar(out, &magic, sizeof(magic));
+  write_scalar(out, &version, sizeof(version));
+  write_scalar(out, &m.n_owned, sizeof(m.n_owned));
+  write_scalar(out, &m.n_remote_ghosts, sizeof(m.n_remote_ghosts));
+  write_scalar(out, &m.n_bc_ghosts, sizeof(m.n_bc_ghosts));
+  write_scalar(out, &m.n_local, sizeof(m.n_local));
+  write_scalar(out, &m.n_boundary_faces, sizeof(m.n_boundary_faces));
+  write_vec(out, m.cx); write_vec(out, m.cy); write_vec(out, m.vol);
+  write_vec(out, m.cell_nv); write_vec(out, m.cell_vert_off); write_vec(out, m.cell_verts);
+  write_vec(out, m.cell_vert_x); write_vec(out, m.cell_vert_y); write_vec(out, m.cell_type);
+  write_vec(out, m.faces); write_vec(out, m.cell_face_off); write_vec(out, m.ghosts);
+  write_vec(out, m.neighbors); write_vec(out, m.send_off); write_vec(out, m.send_cells);
+  write_vec(out, m.recv_off); write_vec(out, m.recv_cells);
+  if (!out) bad("failed while writing partition cache: " + path);
+}
+
+LocalMesh read_local_mesh(const std::string& path) {
+  std::ifstream in(path, std::ios::binary);
+  if (!in) bad("cannot read partition cache: " + path);
+  uint32_t magic = 0, version = 0;
+  read_scalar(in, &magic, sizeof(magic));
+  read_scalar(in, &version, sizeof(version));
+  if (magic != 0x43464432u) bad("bad partition cache magic: " + path);
+  if (version != 3) bad("unsupported partition cache version in " + path);
+  LocalMesh m;
+  read_scalar(in, &m.n_owned, sizeof(m.n_owned));
+  read_scalar(in, &m.n_remote_ghosts, sizeof(m.n_remote_ghosts));
+  read_scalar(in, &m.n_bc_ghosts, sizeof(m.n_bc_ghosts));
+  read_scalar(in, &m.n_local, sizeof(m.n_local));
+  read_scalar(in, &m.n_boundary_faces, sizeof(m.n_boundary_faces));
+  read_vec(in, m.cx); read_vec(in, m.cy); read_vec(in, m.vol);
+  read_vec(in, m.cell_nv); read_vec(in, m.cell_vert_off); read_vec(in, m.cell_verts);
+  read_vec(in, m.cell_vert_x); read_vec(in, m.cell_vert_y); read_vec(in, m.cell_type);
+  read_vec(in, m.faces); read_vec(in, m.cell_face_off); read_vec(in, m.ghosts);
+  read_vec(in, m.neighbors); read_vec(in, m.send_off); read_vec(in, m.send_cells);
+  read_vec(in, m.recv_off); read_vec(in, m.recv_cells);
+  if (m.n_local != static_cast<int>(m.cx.size())) bad("corrupt local mesh center array");
+  if (m.ghosts.size() + m.n_owned != static_cast<size_t>(m.n_local)) bad("corrupt local mesh ghost count");
+  if (m.cell_face_off.size() != static_cast<size_t>(m.n_owned + 1)) bad("corrupt local mesh face offsets");
+  if (!in) bad("truncated partition cache: " + path);
+  return m;
+}
+
+void write_global_info(const GlobalInfo& info, const std::string& path) {
+  json j;
+  j["nparts"] = info.nparts;
+  j["nverts"] = info.nverts;
+  j["ncells"] = info.ncells;
+  j["nfaces"] = info.nfaces;
+  j["n_boundary_faces"] = info.n_boundary_faces;
+  j["partition_edge_cut"] = info.partition_edge_cut;
