+void write_surface_csv(const std::string& path, const std::vector<SurfaceRow>& local_rows,
+                       MPI_Comm comm) {
+  int rank = 0, nranks = 1;
+  MPI_Comm_rank(comm, &rank);
+  MPI_Comm_size(comm, &nranks);
+  std::vector<SurfacePOD> pod(local_rows.size());
+  for (size_t i = 0; i < local_rows.size(); ++i) {
+    const SurfaceRow& r = local_rows[i];
+    pod[i] = SurfacePOD{r.x, r.y, r.nx, r.ny, r.pressure, r.cp, r.cf, r.rho, r.u, r.v, r.mach, {}};
+    std::snprintf(pod[i].tag, sizeof(pod[i].tag), "%s", r.tag.c_str());
+  }
+  int n = static_cast<int>(pod.size());
+  std::vector<int> counts(nranks);
+  MPI_Gather(&n, 1, MPI_INT, counts.data(), 1, MPI_INT, 0, comm);
+  std::vector<int> displ(nranks);
+  int total = 0;
+  if (rank == 0)
+    for (int r = 0; r < nranks; ++r) { displ[r] = total; total += counts[r]; }
+  MPI_Bcast(&total, 1, MPI_INT, 0, comm);
+  std::vector<SurfacePOD> all(rank == 0 ? static_cast<size_t>(total) : 0);
+  MPI_Datatype pod_type;
+  MPI_Type_contiguous(sizeof(SurfacePOD), MPI_BYTE, &pod_type);
+  MPI_Type_commit(&pod_type);
+  MPI_Gatherv(pod.data(), n, pod_type, all.data(), counts.data(), displ.data(), pod_type, 0, comm);
+  MPI_Type_free(&pod_type);
+  if (rank != 0) return;
+  std::sort(all.begin(), all.end(), [](const SurfacePOD& a, const SurfacePOD& b) {
+    int c = std::strcmp(a.tag, b.tag);
+    if (c != 0) return c < 0;
+    if (std::abs(a.x - b.x) > 1e-12) return a.x < b.x;
+    return a.y < b.y;
+  });
+  std::ofstream out(path);
+  if (!out) bad("cannot write surface CSV: " + path);
+  out << "x,y,nx,ny,pressure,cp,cf,rho,u,v,mach,tag\n";
+  out << std::setprecision(12);
+  for (const SurfacePOD& r : all) {
+    out << r.x << ',' << r.y << ',' << r.nx << ',' << r.ny << ',' << r.pressure << ','
+        << r.cp << ',' << r.cf << ',' << r.rho << ',' << r.u << ',' << r.v << ',' << r.mach
+        << ',' << r.tag << '\n';
+  }
+}
+
+void write_restart(const std::string& path, const LocalMesh& local,
+                   const std::vector<double>& U, const std::vector<double>& Uprev,
+                   double physical_time, long long step, MPI_Comm comm) {
+  int rank = 0;
+  MPI_Comm_rank(comm, &rank);
+  std::vector<int> ids(local.owned_global.begin(), local.owned_global.end());
+  std::vector<double> u(static_cast<size_t>(local.n_owned) * 4);
+  std::vector<double> up(static_cast<size_t>(local.n_owned) * 4);
+  for (int i = 0; i < local.n_owned; ++i)
+    for (int c = 0; c < 4; ++c) { u[4 * i + c] = U[4 * i + c]; up[4 * i + c] = Uprev[4 * i + c]; }
+  std::vector<int> all_ids = gather_ints(ids, comm);
+  std::vector<double> all_u = gather_doubles(u, comm);
+  std::vector<double> all_up = gather_doubles(up, comm);
+  if (rank == 0) {
+    std::ofstream out(path, std::ios::binary);
+    if (!out) bad("cannot write restart file: " + path);
+    uint32_t magic = 0x52535431u, version = 1;
+    int64_t n = static_cast<int64_t>(all_ids.size());
+    out.write(reinterpret_cast<const char*>(&magic), sizeof(magic));
+    out.write(reinterpret_cast<const char*>(&version), sizeof(version));
+    out.write(reinterpret_cast<const char*>(&n), sizeof(n));
+    out.write(reinterpret_cast<const char*>(&physical_time), sizeof(physical_time));
+    out.write(reinterpret_cast<const char*>(&step), sizeof(step));
+    out.write(reinterpret_cast<const char*>(all_ids.data()), static_cast<std::streamsize>(n * sizeof(int)));
+    out.write(reinterpret_cast<const char*>(all_u.data()), static_cast<std::streamsize>(n * 4 * sizeof(double)));
+    out.write(reinterpret_cast<const char*>(all_up.data()), static_cast<std::streamsize>(n * 4 * sizeof(double)));
+    if (!out) bad("failed while writing restart file: " + path);
+  }
+  MPI_Barrier(comm);
+}
+
+bool read_restart(const std::string& path, const LocalMesh& local,
+                  std::vector<double>& U, std::vector<double>& Uprev,
+                  double& physical_time, long long& step, MPI_Comm comm) {
+  int rank = 0;
+  MPI_Comm_rank(comm, &rank);
+  std::ifstream in(path, std::ios::binary);
+  if (!in) {
+    if (rank == 0) std::fprintf(stderr, "restart file not found: %s\n", path.c_str());
+    return false;
+  }
+  uint32_t magic = 0, version = 0;
+  int64_t n = 0;
+  in.read(reinterpret_cast<char*>(&magic), sizeof(magic));
+  in.read(reinterpret_cast<char*>(&version), sizeof(version));
+  in.read(reinterpret_cast<char*>(&n), sizeof(n));
+  in.read(reinterpret_cast<char*>(&physical_time), sizeof(physical_time));
+  in.read(reinterpret_cast<char*>(&step), sizeof(step));
+  if (!in || magic != 0x52535431u || version != 1 || n <= 0)
+    bad("invalid restart file: " + path);
+  std::vector<int> ids(n);
+  std::vector<double> u(static_cast<size_t>(n) * 4), up(static_cast<size_t>(n) * 4);
+  in.read(reinterpret_cast<char*>(ids.data()), static_cast<std::streamsize>(n * sizeof(int)));
+  in.read(reinterpret_cast<char*>(u.data()), static_cast<std::streamsize>(n * 4 * sizeof(double)));
+  in.read(reinterpret_cast<char*>(up.data()), static_cast<std::streamsize>(n * 4 * sizeof(double)));
+  if (!in) bad("truncated restart file: " + path);
+  std::unordered_map<int, int64_t> map;
+  map.reserve(static_cast<size_t>(n) * 2);
+  for (int64_t i = 0; i < n; ++i) map[ids[i]] = i;
+  for (int i = 0; i < local.n_owned; ++i) {
+    auto it = map.find(local.owned_global[i]);
+    if (it == map.end()) bad("restart file does not contain every local cell");
+    for (int c = 0; c < 4; ++c) {
+      U[4 * i + c] = u[4 * it->second + c];
+      Uprev[4 * i + c] = up[4 * it->second + c];
+    }
+  }
+  return true;
+}
