+constexpr double kEps = 1e-12;
+
+[[noreturn]] void bad(const std::string& msg) { throw std::runtime_error(msg); }
+
+void mat4_identity(double* A) {
+  for (int i = 0; i < 16; ++i) A[i] = (i % 5 == 0) ? 1.0 : 0.0;
+}
+
+void mat4_mul_vec(const double* A, const double* x, double* y) {
+  for (int i = 0; i < 4; ++i) {
+    y[i] = 0.0;
+    for (int j = 0; j < 4; ++j) y[i] += A[4 * i + j] * x[j];
+  }
+}
+
+bool mat4_inverse(const double* A, double* inv) {
+  double a[4][8];
+  for (int i = 0; i < 4; ++i) {
+    for (int j = 0; j < 4; ++j) a[i][j] = A[4 * i + j];
+    for (int j = 0; j < 4; ++j) a[i][4 + j] = (i == j) ? 1.0 : 0.0;
+  }
+  for (int col = 0; col < 4; ++col) {
+    int pivot = col;
+    for (int r = col + 1; r < 4; ++r)
+      if (std::abs(a[r][col]) > std::abs(a[pivot][col])) pivot = r;
+    if (std::abs(a[pivot][col]) < 1e-300) return false;
+    if (pivot != col)
+      for (int j = 0; j < 8; ++j) std::swap(a[pivot][j], a[col][j]);
+    const double d = a[col][col];
+    for (int j = 0; j < 8; ++j) a[col][j] /= d;
+    for (int r = 0; r < 4; ++r) {
+      if (r == col) continue;
+      const double f = a[r][col];
+      if (f == 0.0) continue;
+      for (int j = 0; j < 8; ++j) a[r][j] -= f * a[col][j];
+    }
+  }
+  for (int i = 0; i < 4; ++i)
+    for (int j = 0; j < 4; ++j) inv[4 * i + j] = a[i][4 + j];
+  return true;
+}
+
+double harten_abs(double lambda, double delta) {
+  const double al = std::abs(lambda);
+  if (al >= delta) return al;
+  return 0.5 * (lambda * lambda / delta + delta);
+}
+
+}  / namespace
+
+FlowSolver::FlowSolver(const CaseConfig& cfg, const LocalMesh& mesh, const GlobalInfo& ginfo,
+                       MPI_Comm comm, const std::string& output_dir, int report_level)
+    : cfg_(cfg), m_(mesh), ginfo_(ginfo), comm_(comm), output_dir_(output_dir),
+      report_level_(report_level) {
+  MPI_Comm_rank(comm_, &rank_);
+  MPI_Comm_size(comm_, &nranks_);
+  gamma_ = cfg_.gas.gamma;
+  Rgas_ = cfg_.gas.R;
+  prandtl_ = cfg_.gas.prandtl;
+  cp_ = gamma_ * Rgas_ / (gamma_ - 1.0);
+  rho_inf_ = cfg_.freestream.rho;
+  u_inf_ = cfg_.freestream.u;
+  v_inf_ = cfg_.freestream.v;
+  p_inf_ = cfg_.freestream.pressure;
+  T_inf_ = p_inf_ / (rho_inf_ * Rgas_);
+  a_inf_ = std::sqrt(gamma_ * p_inf_ / rho_inf_);
+  q_inf_ = 0.5 * rho_inf_ * (u_inf_ * u_inf_ + v_inf_ * v_inf_);
+  mu_ = cfg_.viscous()
+      ? rho_inf_ * cfg_.freestream.velocity_magnitude * cfg_.reference.length / cfg_.reynolds
+      : 0.0;
+  kappa_visc_ = std::max(4.0 / 3.0, gamma_ / prandtl_);
+  const double aoa = cfg_.freestream.aoa_deg * M_PI / 180.0;
+  drag_x_ = std::cos(aoa); drag_y_ = std::sin(aoa);
+  lift_x_ = -std::sin(aoa); lift_y_ = std::cos(aoa);
+  transient_ = cfg_.transient();
+
+  U_.assign(static_cast<size_t>(4 * m_.n_local), 0.0);
+  Uprev_.assign(static_cast<size_t>(4 * m_.n_local), 0.0);
+  prim_.assign(static_cast<size_t>(5 * m_.n_local), 0.0);
+  grad_.assign(static_cast<size_t>(10 * m_.n_local), 0.0);
+  lim_.assign(static_cast<size_t>(4 * m_.n_local), 1.0);
+  res_.assign(static_cast<size_t>(4 * m_.n_owned), 0.0);
+  cell_conv_sum_.assign(static_cast<size_t>(m_.n_owned), 0.0);
+  cell_visc_sum_.assign(static_cast<size_t>(m_.n_owned), 0.0);
+  face_lambda_.assign(m_.faces.size(), 0.0);
+  face_jac_.assign(static_cast<size_t>(16) * m_.faces.size(), 0.0);
+  diag_inv_.assign(static_cast<size_t>(16) * m_.n_owned, 0.0);
+  delta_.assign(static_cast<size_t>(4 * m_.n_owned), 0.0);
+
+  if (rank_ == 0) {
+    std::error_code ec;
+    fs::create_directories(output_dir_, ec);
+    if (ec) bad("cannot create output directory: " + output_dir_ + ": " + ec.message());
+    log_.open(output_dir_ + "/stdout.log", std::ios::out | std::ios::trunc);
+  }
+}
+
+void FlowSolver::log(const std::string& msg) {
+  if (rank_ != 0) return;
+  std::cout << msg << std::endl;
+  if (log_) log_ << msg << '\n';
+}
+
+double FlowSolver::sound_speed(double rho, double p) const {
+  return std::sqrt(gamma_ * p / std::max(rho, kEps));
+}
+
+void FlowSolver::conservative_from_primitive(double rho, double u, double v, double p,
+                                             std::array<double, 4>& out) const {
+  out[0] = rho;
+  out[1] = rho * u;
+  out[2] = rho * v;
+  out[3] = p / (gamma_ - 1.0) + 0.5 * rho * (u * u + v * v);
+}
+
+void FlowSolver::primitive_from_conservative(const std::array<double, 4>& U,
+                                             std::array<double, 5>& out) const {
+  const double rho = U[0];
+  if (!(rho > kEps) || !std::isfinite(rho)) bad("non-positive density encountered");
+  const double u = U[1] / rho;
+  const double v = U[2] / rho;
+  const double p = (gamma_ - 1.0) * (U[3] - 0.5 * (U[1] * U[1] + U[2] * U[2]) / rho);
+  if (!(p > kEps) || !std::isfinite(p)) bad("non-positive pressure encountered");
+  out[0] = rho;
+  out[1] = u;
+  out[2] = v;
+  out[3] = p;
+  out[4] = p / (rho * Rgas_);
+}
+
+std::array<double, 5> FlowSolver::freestream_primitive() const {
+  return {rho_inf_, u_inf_, v_inf_, p_inf_, T_inf_};
+}
+
+std::array<double, 4> FlowSolver::freestream_conservative() const {
+  std::array<double, 4> U;
+  conservative_from_primitive(rho_inf_, u_inf_, v_inf_, p_inf_, U);
+  return U;
+}
+
+void FlowSolver::exchange_vector(std::vector<double>& field, int width) {
+  if (nranks_ == 1) return;
+  const int nsend = static_cast<int>(m_.send_cells.size());
+  const int nrecv = static_cast<int>(m_.recv_cells.size());
+  std::vector<double> sendbuf(static_cast<size_t>(nsend) * width, 0.0);
+  std::vector<double> recvbuf(static_cast<size_t>(nrecv) * width, 0.0);
+  std::vector<MPI_Request> reqs;
+  reqs.reserve(2 * m_.neighbors.size());
+  for (size_t k = 0; k < m_.neighbors.size(); ++k) {
+    const int count = (m_.recv_off[k + 1] - m_.recv_off[k]) * width;
+    MPI_Request req;
+    MPI_Irecv(recvbuf.data() + static_cast<size_t>(m_.recv_off[k]) * width, count,
+              MPI_DOUBLE, m_.neighbors[k], 300 + static_cast<int>(k), comm_, &req);
+    reqs.push_back(req);
+  }
+  for (size_t k = 0; k < m_.neighbors.size(); ++k) {
+    for (int e = m_.send_off[k]; e < m_.send_off[k + 1]; ++e) {
+      const int cell = m_.send_cells[e];
+      for (int c = 0; c < width; ++c)
+        sendbuf[static_cast<size_t>(e) * width + c] = field[static_cast<size_t>(cell) * width + c];
+    }
+    const int count = (m_.send_off[k + 1] - m_.send_off[k]) * width;
+    MPI_Request req;
+    MPI_Isend(sendbuf.data() + static_cast<size_t>(m_.send_off[k]) * width, count,
+              MPI_DOUBLE, m_.neighbors[k], 300 + static_cast<int>(k), comm_, &req);
+    reqs.push_back(req);
+  }
+  if (!reqs.empty()) MPI_Waitall(static_cast<int>(reqs.size()), reqs.data(), MPI_STATUSES_IGNORE);
+  for (size_t k = 0; k < m_.neighbors.size(); ++k) {
+    for (int e = m_.recv_off[k]; e < m_.recv_off[k + 1]; ++e) {
+      const int ghost = m_.recv_cells[e];
+      for (int c = 0; c < width; ++c)
+        field[static_cast<size_t>(ghost) * width + c] = recvbuf[static_cast<size_t>(e) * width + c];
+    }
+  }
+}
+
+void FlowSolver::exchange_U() { exchange_vector(U_, 4); }
+void FlowSolver::exchange_gradients() { exchange_vector(grad_, 10); }
+void FlowSolver::exchange_limiters() { exchange_vector(lim_, 4); }
+
+void FlowSolver::compute_primitives() {
+  for (int i = 0; i < m_.n_local; ++i) {
+    std::array<double, 4> U{{U_[4 * i], U_[4 * i + 1], U_[4 * i + 2], U_[4 * i + 3]}};
+    std::array<double, 5> q;
+    primitive_from_conservative(U, q);
+    for (int c = 0; c < 5; ++c) prim_[5 * i + c] = q[c];
+  }
+}
+
+void FlowSolver::apply_boundary_ghost_states() {
+  const std::array<double, 5> qinf = freestream_primitive();
+  std::array<double, 4> Uinf;
+  conservative_from_primitive(qinf[0], qinf[1], qinf[2], qinf[3], Uinf);
+  for (int gi = 0; gi < static_cast<int>(m_.ghosts.size()); ++gi) {
+    const GhostCell& g = m_.ghosts[gi];
+    if (g.kind == 0) continue;
+    const int gj = m_.n_owned + gi;
+    if (g.kind == static_cast<int>(BoundaryKind::Farfield)) {
+      for (int c = 0; c < 5; ++c) prim_[5 * gj + c] = qinf[c];
+      for (int c = 0; c < 4; ++c) U_[4 * gj + c] = Uinf[c];
+      continue;
+    }
+    const int i = g.bc_owner;
+    const double rho = prim_[5 * i + 0];
+    const double u = prim_[5 * i + 1];
+    const double v = prim_[5 * i + 2];
+    const double p = prim_[5 * i + 3];
+    const double T = prim_[5 * i + 4];
+    double ug = u, vg = v;
+    if (g.kind == static_cast<int>(BoundaryKind::SlipWall)) {
+      const double un = u * g.nx + v * g.ny;
+      ug = u - 2.0 * un * g.nx;
+      vg = v - 2.0 * un * g.ny;
+    } else {
+      ug = -u;
+      vg = -v;
+    }
+    prim_[5 * gj + 0] = rho;
+    prim_[5 * gj + 1] = ug;
+    prim_[5 * gj + 2] = vg;
+    prim_[5 * gj + 3] = p;
+    prim_[5 * gj + 4] = T;
+    std::array<double, 4> Ug;
+    conservative_from_primitive(rho, ug, vg, p, Ug);
+    for (int c = 0; c < 4; ++c) U_[4 * gj + c] = Ug[c];
+  }
+}
+
+void FlowSolver::apply_boundary_ghost_gradients() {
+  for (int gi = 0; gi < static_cast<int>(m_.ghosts.size()); ++gi) {
+    const GhostCell& g = m_.ghosts[gi];
+    if (g.kind == 0) continue;
+    const int gj = m_.n_owned + gi;
+    for (int q = 0; q < 4; ++q) lim_[4 * gj + q] = 1.0;
+    if (g.kind == static_cast<int>(BoundaryKind::Farfield)) {
+      for (int q = 0; q < 5; ++q) {
+        grad_[10 * gj + 2 * q] = 0.0;
+        grad_[10 * gj + 2 * q + 1] = 0.0;
+      }
+      continue;
+    }
+    const int i = g.bc_owner;
+    for (int q = 0; q < 5; ++q) {
+      const double gx = grad_[10 * i + 2 * q];
+      const double gy = grad_[10 * i + 2 * q + 1];
+      const double dot = gx * g.nx + gy * g.ny;
+      grad_[10 * gj + 2 * q] = gx - 2.0 * dot * g.nx;
+      grad_[10 * gj + 2 * q + 1] = gy - 2.0 * dot * g.ny;
+    }
+  }
+}
+
+void FlowSolver::compute_gradients() {
+  for (int i = 0; i < m_.n_owned; ++i) {
+    double a00 = 0.0, a01 = 0.0, a11 = 0.0;
+    double b[5][2] = {{0.0}};
+    for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+      const int j = m_.faces[fi].nb;
+      const double dx = m_.cx[j] - m_.cx[i];
+      const double dy = m_.cy[j] - m_.cy[i];
+      const double r2 = dx * dx + dy * dy;
+      if (!(r2 > 1e-30)) continue;
+      const double w = 1.0 / r2;
+      a00 += w * dx * dx;
+      a01 += w * dx * dy;
+      a11 += w * dy * dy;
+      for (int q = 0; q < 5; ++q) {
+        const double dq = prim_[5 * j + q] - prim_[5 * i + q];
+        b[q][0] += w * dx * dq;
+        b[q][1] += w * dy * dq;
+      }
+    }
+    const double scale = std::max(1.0, a00 + a11);
+    a00 += 1e-14 * scale;
+    a11 += 1e-14 * scale;
+    const double det = a00 * a11 - a01 * a01;
+    for (int q = 0; q < 5; ++q) {
+      if (std::abs(det) < 1e-40) {
+        grad_[10 * i + 2 * q] = 0.0;
+        grad_[10 * i + 2 * q + 1] = 0.0;
+      } else {
+        grad_[10 * i + 2 * q] = (a11 * b[q][0] - a01 * b[q][1]) / det;
+        grad_[10 * i + 2 * q + 1] = (a00 * b[q][1] - a01 * b[q][0]) / det;
+        if (!std::isfinite(grad_[10 * i + 2 * q]) || !std::isfinite(grad_[10 * i + 2 * q + 1]))
+          bad("non-finite gradient in cell " + std::to_string(m_.owned_global[i]));
+      }
+    }
+  }
+}
+
+void FlowSolver::compute_limiters() {
+  for (int i = 0; i < m_.n_owned; ++i) {
+    for (int q = 0; q < 4; ++q) {
+      const double qi = prim_[5 * i + q];
+      double qmin = qi, qmax = qi;
+      for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+        const int j = m_.faces[fi].nb;
+        const double qj = prim_[5 * j + q];
+        qmin = std::min(qmin, qj);
+        qmax = std::max(qmax, qj);
+      }
+      double phi = 1.0;
+      for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+        const int j = m_.faces[fi].nb;
+        const double dx = m_.cx[j] - m_.cx[i];
+        const double dy = m_.cy[j] - m_.cy[i];
+        const double dq = grad_[10 * i + 2 * q] * dx + grad_[10 * i + 2 * q + 1] * dy;
+        if (dq > 1e-30) {
+          phi = std::min(phi, (qmax - qi) / dq);
+        } else if (dq < -1e-30) {
+          phi = std::min(phi, (qmin - qi) / dq);
+        }
+      }
+      phi = std::min(1.0, std::max(0.0, phi));
+      if (!std::isfinite(phi)) phi = 0.0;
+      lim_[4 * i + q] = phi;
+    }
+  }
+}
+
+void FlowSolver::prepare_state() {
+  exchange_U();
+  compute_primitives();
+  apply_boundary_ghost_states();
+  compute_gradients();
+  exchange_gradients();
+  apply_boundary_ghost_gradients();
+  compute_limiters();
+  exchange_limiters();
+  for (int gi = 0; gi < static_cast<int>(m_.ghosts.size()); ++gi)
+    if (m_.ghosts[gi].kind != 0)
+      for (int q = 0; q < 4; ++q) lim_[4 * (m_.n_owned + gi) + q] = 1.0;
+}
+
+void FlowSolver::reconstruct_face(int i, int j, const LocalFace& f,
+                                  std::array<double, 4>& qL, std::array<double, 4>& qR,
+                                  bool& first_order) {
+  const double dxL = f.xf - m_.cx[i];
+  const double dyL = f.yf - m_.cy[i];
+  const double dxR = f.xf - m_.cx[j];
+  const double dyR = f.yf - m_.cy[j];
+  for (int q = 0; q < 4; ++q) {
+    qL[q] = prim_[5 * i + q] + lim_[4 * i + q] *
+        (grad_[10 * i + 2 * q] * dxL + grad_[10 * i + 2 * q + 1] * dyL);
+    qR[q] = prim_[5 * j + q] + lim_[4 * j + q] *
+        (grad_[10 * j + 2 * q] * dxR + grad_[10 * j + 2 * q + 1] * dyR);
+  }
+  first_order = false;
+  if (!(qL[0] > kEps) || !(qL[3] > kEps) || !(qR[0] > kEps) || !(qR[3] > kEps) ||
+      !std::isfinite(qL[0]) || !std::isfinite(qL[3]) ||
+      !std::isfinite(qR[0]) || !std::isfinite(qR[3])) {
+    for (int q = 0; q < 4; ++q) {
+      qL[q] = prim_[5 * i + q];
+      qR[q] = prim_[5 * j + q];
+    }
+    first_order = true;
+  }
+}
+
+std::array<double, 4> FlowSolver::rusanov_flux(const std::array<double, 4>& UL,
+                                               const std::array<double, 4>& UR,
+                                               double nx, double ny) const {
+  std::array<double, 5> pL, pR;
+  primitive_from_conservative(UL, pL);
+  primitive_from_conservative(UR, pR);
+  const double unL = pL[1] * nx + pL[2] * ny;
+  const double unR = pR[1] * nx + pR[2] * ny;
+  const double aL = sound_speed(pL[0], pL[3]);
+  const double aR = sound_speed(pR[0], pR[3]);
+  std::array<double, 4> FL{{pL[0] * unL,
+                            pL[0] * pL[1] * unL + pL[3] * nx,
+                            pL[0] * pL[2] * unL + pL[3] * ny,
+                            unL * (UL[3] + pL[3])}};
+  std::array<double, 4> FR{{pR[0] * unR,
+                            pR[0] * pR[1] * unR + pR[3] * nx,
+                            pR[0] * pR[2] * unR + pR[3] * ny,
+                            unR * (UR[3] + pR[3])}};
+  const double lambda = std::max(std::abs(unL) + aL, std::abs(unR) + aR);
+  std::array<double, 4> F;
+  for (int c = 0; c < 4; ++c)
+    F[c] = 0.5 * (FL[c] + FR[c]) - 0.5 * lambda * (UR[c] - UL[c]) *
+        (transient_ ? cfg_.run.rusanov_dissipation_scale : 1.0);
+  return F;
+}
+
+std::array<double, 4> FlowSolver::roe_flux(const std::array<double, 4>& UL,
+                                           const std::array<double, 4>& UR,
+                                           double nx, double ny) const {
+  std::array<double, 5> pL, pR;
+  primitive_from_conservative(UL, pL);
+  primitive_from_conservative(UR, pR);
+  const double rhoL = pL[0], uL = pL[1], vL = pL[2], pLp = pL[3];
+  const double rhoR = pR[0], uR = pR[1], vR = pR[2], pRp = pR[3];
+  const double unL = uL * nx + vL * ny;
+  const double unR = uR * nx + vR * ny;
+  const double utL = -uL * ny + vL * nx;
+  const double utR = -uR * ny + vR * nx;
+  const double aL = sound_speed(rhoL, pLp);
+  const double aR = sound_speed(rhoR, pRp);
+  std::array<double, 4> FL{{rhoL * unL,
+                            rhoL * uL * unL + pLp * nx,
+                            rhoL * vL * unL + pLp * ny,
+                            unL * (UL[3] + pLp)}};
+  std::array<double, 4> FR{{rhoR * unR,
+                            rhoR * uR * unR + pRp * nx,
+                            rhoR * vR * unR + pRp * ny,
+                            unR * (UR[3] + pRp)}};
+  const double HL = (UL[3] + pLp) / rhoL;
+  const double HR = (UR[3] + pRp) / rhoR;
+  const double sL = std::sqrt(rhoL), sR = std::sqrt(rhoR);
+  const double sum = sL + sR;
+  const double wL = sL / sum, wR = sR / sum;
+  const double u = wL * uL + wR * uR;
+  const double v = wL * vL + wR * vR;
+  const double H = wL * HL + wR * HR;
+  const double q2 = u * u + v * v;
+  double a2 = (gamma_ - 1.0) * (H - 0.5 * q2);
+  if (!(a2 > 1e-14)) return rusanov_flux(UL, UR, nx, ny);
+  const double a = std::sqrt(a2);
+  const double un = u * nx + v * ny;
+  const double ut = -u * ny + v * nx;
+  const double rho_tilde = sL * sR;
+  const double dp = pRp - pLp;
+  const double drho = rhoR - rhoL;
+  const double dun = unR - unL;
+  const double dut = utR - utL;
+  const double alpha1 = 0.5 * (dp - rho_tilde * a * dun) / a2;
+  const double alpha2 = drho - dp / a2;
+  const double alpha3 = rho_tilde * dut;
+  const double alpha4 = 0.5 * (dp + rho_tilde * a * dun) / a2;
+  const double delta = 0.1 * (std::abs(un) + a);
+  const double l1 = harten_abs(un - a, delta);
+  const double l2 = harten_abs(un, delta);
+  const double l3 = l2;
+  const double l4 = harten_abs(un + a, delta);
+  std::array<double, 4> d{{0.0, 0.0, 0.0, 0.0}};
+  d[0] = l1 * alpha1 + l2 * alpha2 + l4 * alpha4;
+  d[1] = l1 * alpha1 * (un - a) + l2 * alpha2 * un + l4 * alpha4 * (un + a);
+  d[2] = l1 * alpha1 * ut + l2 * alpha2 * ut + l3 * alpha3 + l4 * alpha4 * ut;
