+void euler_jacobian_n(const std::array<double, 4>& U, double nx, double ny,
+                      double gamma, double* A) {
+  const double g1 = gamma - 1.0;
+  const double rho = U[0];
+  const double u = U[1] / rho;
+  const double v = U[2] / rho;
+  const double E = U[3] / rho;
+  const double q2 = u * u + v * v;
+  const double p = g1 * (U[3] - 0.5 * rho * q2);
+  const double H = (E + p) / rho;
+  const double un = u * nx + v * ny;
+  for (int i = 0; i < 16; ++i) A[i] = 0.0;
+  A[0] = 0.0; A[1] = nx; A[2] = ny; A[3] = 0.0;
+  A[4] = g1 * 0.5 * q2 * nx - u * un;
+  A[5] = (2.0 - g1) * u * nx + v * ny;
+  A[6] = u * ny - g1 * v * nx;
+  A[7] = g1 * nx;
+  A[8] = g1 * 0.5 * q2 * ny - v * un;
+  A[9] = v * nx - g1 * u * ny;
+  A[10] = u * nx + (2.0 - g1) * v * ny;
+  A[11] = g1 * ny;
+  A[12] = un * (g1 * 0.5 * q2 - H);
+  A[13] = H * nx - g1 * u * un;
+  A[14] = H * ny - g1 * v * un;
+  A[15] = gamma * un;
+}
