+      reconstruct_face(i, j, f, qL, qR, first_order);
+      ++visited_faces_;
+      if (first_order) ++first_order_faces_;
+      bool limited = false;
+      for (int q = 0; q < 4; ++q) {
+        if (lim_[4 * i + q] < 0.9999 || lim_[4 * j + q] < 0.9999) limited = true;
+      }
+      if (limited) ++limited_faces_;
+
+      const double rhoL = qL[0], uL = qL[1], vL = qL[2], pL = qL[3];
+      const double rhoR = qR[0], uR = qR[1], vR = qR[2], pR = qR[3];
+      const double unL = uL * f.nx + vL * f.ny;
+      const double unR = uR * f.nx + vR * f.ny;
+      const double aL = sound_speed(rhoL, pL);
+      const double aR = sound_speed(rhoR, pR);
+      const double lambda = std::max(std::abs(unL) + aL, std::abs(unR) + aR) * f.area;
+      face_lambda_[fi] = lambda;
+      sum_lambda += lambda;
+
+      std::array<double, 4> Finv{{0.0, 0.0, 0.0, 0.0}};
+      if (f.bc == static_cast<int>(BoundaryKind::SlipWall) ||
+          f.bc == static_cast<int>(BoundaryKind::NoSlipAdiabaticWall)) {
