+      viscous_flux(i, j, f, f.nx, f.ny, Fv);
+      const double scale = f.area / m_.vol[i];
+      for (int c = 0; c < 4; ++c) R[c] -= (Finv[c] - Fv[c]) * scale;
+
+      if (cfg_.viscous() && f.bc != static_cast<int>(BoundaryKind::SlipWall)) {
+        const double d = std::hypot(m_.cx[j] - m_.cx[i], m_.cy[j] - m_.cy[i]);
+        const double rho_face = std::max(0.5 * (rhoL + rhoR), kEps);
