+ResidualNorm FlowSolver::global_norm() const {
+  double local_l2 = 0.0, local_linf = 0.0;
+  double local_comp[4] = {0.0, 0.0, 0.0, 0.0};
+  double total_vol = 0.0;
+  for (int i = 0; i < m_.n_owned; ++i) {
+    const double v = m_.vol[i];
+    total_vol += v;
+    for (int c = 0; c < 4; ++c) {
+      const double r = res_[4 * i + c];
+      local_l2 += r * r * v;
+      local_comp[c] += r * r * v;
+      local_linf = std::max(local_linf, std::abs(r));
+    }
+  }
+  double sum_l2 = 0.0, sum_vol = 0.0, sum_comp[4] = {0.0, 0.0, 0.0, 0.0}, max_linf = 0.0;
+  MPI_Allreduce(&local_l2, &sum_l2, 1, MPI_DOUBLE, MPI_SUM, comm_);
+  MPI_Allreduce(&total_vol, &sum_vol, 1, MPI_DOUBLE, MPI_SUM, comm_);
+  MPI_Allreduce(local_comp, sum_comp, 4, MPI_DOUBLE, MPI_SUM, comm_);
+  MPI_Allreduce(&local_linf, &max_linf, 1, MPI_DOUBLE, MPI_MAX, comm_);
+  ResidualNorm n;
+  n.linf = max_linf;
+  if (sum_vol > 0.0) {
+    n.l2 = std::sqrt(sum_l2 / sum_vol);
+    for (int c = 0; c < 4; ++c) n.component[c] = std::sqrt(sum_comp[c] / sum_vol);
+  }
+  return n;
+}
