+void FlowSolver::build_jacobian(double cfl, bool transient, int bdf_order, double dt_phys) {
+  std::fill(face_jac_.begin(), face_jac_.end(), 0.0);
+  std::fill(diag_inv_.begin(), diag_inv_.end(), 0.0);
+  const double a0 = (bdf_order == 2) ? 1.5 : 1.0;
+  for (int i = 0; i < m_.n_owned; ++i) {
+    const double sum = cell_conv_sum_[i] + cell_visc_sum_[i];
+    double diag = sum / std::max(cfl, 1e-6);
+    if (transient) {
+      if (!(dt_phys > 0.0)) bad("non-positive physical time step in Jacobian");
+      diag += a0 * m_.vol[i] / dt_phys;
+    }
+    if (!(diag > 0.0) || !std::isfinite(diag)) diag = 1.0;
+    double D[16];
+    for (int k = 0; k < 16; ++k) D[k] = 0.0;
+    D[0] = D[5] = D[10] = D[15] = diag;
+    if (!mat4_inverse(D, &diag_inv_[16 * i])) {
+      for (int k = 0; k < 4; ++k) D[5 * k] += 1e-8 * diag;
+      if (!mat4_inverse(D, &diag_inv_[16 * i])) mat4_identity(&diag_inv_[16 * i]);
+    }
+    for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+      const LocalFace& f = m_.faces[fi];
+      if (f.nb >= m_.n_owned) continue;
+      std::array<double, 4> Uj{{U_[4 * f.nb], U_[4 * f.nb + 1], U_[4 * f.nb + 2], U_[4 * f.nb + 3]}};
+      double A[16];
