+      const double lambda_area = face_lambda_[fi];
+      for (int k = 0; k < 16; ++k) face_jac_[16 * fi + k] = 0.5 * A[k] * f.area;
+      for (int k = 0; k < 4; ++k) face_jac_[16 * fi + 5 * k] -= 0.5 * lambda_area;
+    }
+  }
