+void FlowSolver::solve_lu_sgs(int sweeps) {
+  std::fill(delta_.begin(), delta_.end(), 0.0);
+  for (int sweep = 0; sweep < sweeps; ++sweep) {
+    for (int i = 0; i < m_.n_owned; ++i) {
+      double r[4] = {-res_[4 * i], -res_[4 * i + 1], -res_[4 * i + 2], -res_[4 * i + 3]};
+      for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+        const LocalFace& f = m_.faces[fi];
+        const int j = f.nb;
+        if (j >= m_.n_owned || j >= i) continue;
+        double t[4];
+        mat4_mul_vec(&face_jac_[16 * fi], &delta_[4 * j], t);
+        for (int c = 0; c < 4; ++c) r[c] -= t[c];
+      }
+      double d[4];
+      mat4_mul_vec(&diag_inv_[16 * i], r, d);
+      for (int c = 0; c < 4; ++c) delta_[4 * i + c] = d[c];
+    }
+    for (int i = m_.n_owned - 1; i >= 0; --i) {
+      double r[4] = {-res_[4 * i], -res_[4 * i + 1], -res_[4 * i + 2], -res_[4 * i + 3]};
+      for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+        const LocalFace& f = m_.faces[fi];
+        const int j = f.nb;
+        if (j >= m_.n_owned || j <= i) continue;
+        double t[4];
+        mat4_mul_vec(&face_jac_[16 * fi], &delta_[4 * j], t);
+        for (int c = 0; c < 4; ++c) r[c] -= t[c];
+      }
+      double d[4];
+      mat4_mul_vec(&diag_inv_[16 * i], r, d);
+      for (int c = 0; c < 4; ++c) delta_[4 * i + c] = d[c];
+    }
+  }
