+bool FlowSolver::apply_delta(double omega) {
+  std::vector<double> newU(static_cast<size_t>(4 * m_.n_owned));
+  for (int i = 0; i < m_.n_owned; ++i) {
+    for (int c = 0; c < 4; ++c)
+      newU[4 * i + c] = U_[4 * i + c] + omega * delta_[4 * i + c];
+    const double rho = newU[4 * i];
+    const double mx = newU[4 * i + 1];
+    const double my = newU[4 * i + 2];
+    const double E = newU[4 * i + 3];
+    if (!(rho > kEps) || !std::isfinite(rho) || !std::isfinite(mx) ||
+        !std::isfinite(my) || !std::isfinite(E)) return false;
+    const double p = (gamma_ - 1.0) * (E - 0.5 * (mx * mx + my * my) / rho);
+    if (!(p > kEps) || !std::isfinite(p)) return false;
+  }
+  for (int i = 0; i < m_.n_owned; ++i)
+    for (int c = 0; c < 4; ++c) U_[4 * i + c] = newU[4 * i + c];
+  return true;
