+double FlowSolver::mean_pseudo_dt(double cfl) const {
+  double local = 0.0;
+  for (int i = 0; i < m_.n_owned; ++i) {
+    const double sum = cell_conv_sum_[i] + cell_visc_sum_[i];
+    local += cfl * m_.vol[i] / std::max(sum, 1e-30);
