+ForceCoeffs FlowSolver::compute_forces() const {
+  double Fpx = 0.0, Fpy = 0.0, Fvx = 0.0, Fvy = 0.0, Mz = 0.0;
+  const double mx = cfg_.reference.moment_x, my = cfg_.reference.moment_y;
