+      if (!(pwall > kEps) || !std::isfinite(pwall)) pwall = prim_[5 * i + 3];
+      const double pfx = pwall * f.nx * f.area;
+      const double pfy = pwall * f.ny * f.area;
+      Fpx += pfx; Fpy += pfy;
+      Mz += (f.xf - mx) * pfy - (f.yf - my) * pfx;
+      if (cfg_.viscous()) {
