+        Mz += (f.xf - mx) * fy - (f.yf - my) * fx;
+      }
+    }
+  }
+  double local[5] = {Fpx, Fpy, Fvx, Fvy, Mz};
+  double global[5] = {0, 0, 0, 0, 0};
+  MPI_Allreduce(local, global, 5, MPI_DOUBLE, MPI_SUM, comm_);
+  ForceCoeffs out;
+  const double qA = q_inf_ * cfg_.reference.area;
+  out.force_x = global[0] + global[2];
+  out.force_y = global[1] + global[3];
+  out.moment_z = global[4];
+  out.pressure_drag = (global[0] * drag_x_ + global[1] * drag_y_) / qA;
+  out.pressure_lift = (global[0] * lift_x_ + global[1] * lift_y_) / qA;
+  out.viscous_drag = (global[2] * drag_x_ + global[3] * drag_y_) / qA;
+  out.viscous_lift = (global[2] * lift_x_ + global[3] * lift_y_) / qA;
+  out.cd = out.pressure_drag + out.viscous_drag;
+  out.cl = out.pressure_lift + out.viscous_lift;
+  out.cmz = global[4] / (qA * cfg_.reference.length);
