+void FlowSolver::collect_surface(std::vector<SurfaceRow>& rows) const {
+  rows.clear();
+  for (int i = 0; i < m_.n_owned; ++i) {
+    for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+      const LocalFace& f = m_.faces[fi];
+      const bool slip = f.bc == static_cast<int>(BoundaryKind::SlipWall);
+      const bool noslip = f.bc == static_cast<int>(BoundaryKind::NoSlipAdiabaticWall);
+      if (!slip && !noslip) continue;
+      const double dx = f.xf - m_.cx[i];
+      const double dy = f.yf - m_.cy[i];
+      double pwall = prim_[5 * i + 3] + lim_[4 * i + 3] *
+          (grad_[10 * i + 6] * dx + grad_[10 * i + 7] * dy);
+      if (!(pwall > kEps) || !std::isfinite(pwall)) pwall = prim_[5 * i + 3];
+      double rhow = prim_[5 * i + 0] + lim_[4 * i + 0] *
+          (grad_[10 * i + 0] * dx + grad_[10 * i + 1] * dy);
+      if (!(rhow > kEps) || !std::isfinite(rhow)) rhow = prim_[5 * i + 0];
+      const double aw = sound_speed(rhow, pwall);
+      SurfaceRow r;
+      r.x = f.xf; r.y = f.yf;
+      r.nx = -f.nx; r.ny = -f.ny;
+      r.pressure = pwall;
+      r.cp = (pwall - p_inf_) / q_inf_;
+      r.rho = rhow;
+      if (noslip) {
+        r.u = 0.0; r.v = 0.0; r.mach = 0.0;
+      } else {
+        const double ui = prim_[5 * i + 1];
+        const double vi = prim_[5 * i + 2];
+        const double un = ui * f.nx + vi * f.ny;
+        r.u = ui - un * f.nx;
+        r.v = vi - un * f.ny;
+        r.mach = std::hypot(r.u, r.v) / aw;
+      }
+      r.cf = 0.0;
+      if (cfg_.viscous() && noslip) {
+        double tnx, tny;
+        wall_traction(i, f, tnx, tny);
+        const double tn = tnx * f.nx + tny * f.ny;
+        const double tx = tnx - tn * f.nx;
+        const double ty = tny - tn * f.ny;
+        r.cf = (tx * drag_x_ + ty * drag_y_) / q_inf_;
+      }
+      r.tag = ginfo_.family_names.at(static_cast<size_t>(f.tag));
+      rows.push_back(std::move(r));
+    }
+  }
