+  for (int i = 0; i < m_.n_owned; ++i) {
+    for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+      const LocalFace& f = m_.faces[fi];
+      if (f.bc != static_cast<int>(BoundaryKind::NoSlipAdiabaticWall)) continue;
+      const double tx = -f.ny, ty = f.nx;
+      const double h = 0.5 * f.area;
+      local.push_back(f.xf - h * tx);
+      local.push_back(f.yf - h * ty);
+      local.push_back(f.xf + h * tx);
+      local.push_back(f.yf + h * ty);
+    }
+  }
+  int rank = 0, nranks = 1;
+  MPI_Comm_rank(comm_, &rank);
+  MPI_Comm_size(comm_, &nranks);
+  int nlocal = static_cast<int>(local.size());
+  std::vector<int> counts(nranks), displ(nranks);
+  MPI_Gather(&nlocal, 1, MPI_INT, counts.data(), 1, MPI_INT, 0, comm_);
+  int total = 0;
+  if (rank == 0)
+    for (int r = 0; r < nranks; ++r) { displ[r] = total; total += counts[r]; }
+  MPI_Bcast(&total, 1, MPI_INT, 0, comm_);
+  std::vector<double> all(static_cast<size_t>(std::max(0, total)));
+  MPI_Allgatherv(local.data(), nlocal, MPI_DOUBLE, all.data(), counts.data(), displ.data(),
+                 MPI_DOUBLE, comm_);
+  const int nseg = total / 4;
+  const double Vinf = cfg_.freestream.velocity_magnitude;
+  const double delta = std::max(0.02, 5.0 / std::sqrt(std::max(cfg_.reynolds, 1.0)));
+  for (int i = 0; i < m_.n_owned; ++i) {
+    double dmin = 1e300;
+    for (int s = 0; s < nseg; ++s) {
+      const double ax = all[4 * s], ay = all[4 * s + 1];
+      const double bx = all[4 * s + 2], by = all[4 * s + 3];
+      const double vx = bx - ax, vy = by - ay;
+      const double wx = m_.cx[i] - ax, wy = m_.cy[i] - ay;
+      const double len2 = vx * vx + vy * vy;
+      double t = len2 > 0.0 ? (wx * vx + wy * vy) / len2 : 0.0;
+      t = std::min(1.0, std::max(0.0, t));
+      const double dx = m_.cx[i] - (ax + t * vx);
