+
+void FlowSolver::apply_slip_initial_projection() {
+  / A uniform freestream imposed on a slip wall carries a finite normal
+  / velocity at the wall, so the first iterate creates an impulsive vortex
+  / sheet.  In an inviscid low-Mach flow that sheet is not diffused and can
+  / organise into a persistent numerical street.  Project the initial velocity
+  / of the wall-adjacent cells onto the local wall tangent instead.  This only
+  / changes the t=0 initial condition.
+  std::vector<double> ux(static_cast<size_t>(m_.n_owned), 0.0);
+  std::vector<double> uy(static_cast<size_t>(m_.n_owned), 0.0);
+  std::vector<int> count(static_cast<size_t>(m_.n_owned), 0);
+  for (int i = 0; i < m_.n_owned; ++i) {
+    for (int fi = m_.cell_face_off[i]; fi < m_.cell_face_off[i + 1]; ++fi) {
+      const LocalFace& f = m_.faces[fi];
+      if (f.bc != static_cast<int>(BoundaryKind::SlipWall)) continue;
+      const double tx = -f.ny, ty = f.nx;
+      const double ut = u_inf_ * tx + v_inf_ * ty;
+      ux[i] += ut * tx;
+      uy[i] += ut * ty;
+      ++count[i];
+    }
+  }
+  for (int i = 0; i < m_.n_owned; ++i) {
+    if (count[i] == 0) continue;
+    const double u = ux[i] / count[i];
+    const double v = uy[i] / count[i];
+    std::array<double, 4> U0;
+    conservative_from_primitive(rho_inf_, u, v, p_inf_, U0);
+    for (int c = 0; c < 4; ++c) { U_[4 * i + c] = U0[c]; Uprev_[4 * i + c] = U0[c]; }
+  }
+  log("slip-wall initial velocity projection applied");
+}
